// CV comparator: Hysteresis converts a continuous LFO to a gate that modulates audio. Gate and trigger are distinct output ports.
// Legacy reference: Main/ui/behaviors/compare_runtime.lua
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  oscillator as oscillatorDefinition,
  lfo as lfoDefinition,
  cvCompare as cvCompareDefinition,
  modulatedGain as modulatedGainDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    oscillator_waveform: {
      "path": "/primitives/compare/node/0",
      "label": "Waveform",
      "group": "Oscillator",
      "min": 0,
      "max": 4,
      "default": 0,
      "choices": [
        "Sine",
        "Saw",
        "Square",
        "Triangle",
        "Blend"
      ]
    },
    oscillator_frequency: {
      "path": "/primitives/compare/node/1",
      "label": "Frequency",
      "group": "Oscillator",
      "min": 20,
      "max": 16000,
      "default": 220
    },
    oscillator_level: {
      "path": "/primitives/compare/node/2",
      "label": "Level",
      "group": "Oscillator",
      "min": 0,
      "max": 1,
      "default": 0.16
    },
    lfo_waveform: {
      "path": "/primitives/compare/lfo/0",
      "label": "Waveform",
      "group": "LFO",
      "min": 0,
      "max": 2,
      "default": 0,
      "choices": [
        "Sine",
        "Triangle",
        "Square"
      ]
    },
    lfo_rate: {
      "path": "/primitives/compare/lfo/1",
      "label": "Rate",
      "group": "LFO",
      "min": 0.05,
      "max": 20,
      "default": 2
    },
    compare_direction: {
      "path": "/primitives/compare/compare/0",
      "label": "Direction",
      "group": "CV compare",
      "min": 0,
      "max": 2,
      "default": 2,
      "choices": [
        "Rise",
        "Fall",
        "Both"
      ]
    },
    compare_threshold: {
      "path": "/primitives/compare/compare/1",
      "label": "Threshold",
      "group": "CV compare",
      "min": -1,
      "max": 1,
      "default": 0.2
    },
    compare_hysteresis: {
      "path": "/primitives/compare/compare/2",
      "label": "Hysteresis",
      "group": "CV compare",
      "min": 0,
      "max": 0.5,
      "default": 0.05
    },
    gain_base: {
      "path": "/primitives/compare/gain/0",
      "label": "Base",
      "group": "CV gain",
      "min": 0,
      "max": 2,
      "default": 0.1
    },
    gain_depth: {
      "path": "/primitives/compare/gain/1",
      "label": "Depth",
      "group": "CV gain",
      "min": -2,
      "max": 2,
      "default": 0.8
    },
  };

  // Audio inputs and outputs — generated sound; no audio input is needed.
  const graph = createGraphWorkspace().setInputSource('none');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const oscillator = graph.add(oscillatorDefinition.type, {"id":4});
  graph.registerInstance('/primitives/compare/node', oscillator);
  oscillator.parameter('waveform').expose(controls.oscillator_waveform);
  oscillator.parameter('frequency').expose(controls.oscillator_frequency);
  oscillator.parameter('level').expose(controls.oscillator_level);

  const lfo = graph.add(lfoDefinition.type, {"id":5});
  graph.registerInstance('/primitives/compare/lfo', lfo);
  lfo.parameter('waveform').expose(controls.lfo_waveform);
  lfo.parameter('rate').expose(controls.lfo_rate);

  const compare = graph.add(cvCompareDefinition.type, {"id":6});
  graph.registerInstance('/primitives/compare/compare', compare);
  compare.parameter('direction').expose(controls.compare_direction);
  compare.parameter('threshold').expose(controls.compare_threshold);
  compare.parameter('hysteresis').expose(controls.compare_hysteresis);

  const gain = graph.add(modulatedGainDefinition.type, {"id":7});
  graph.registerInstance('/primitives/compare/gain', gain);
  gain.parameter('base').expose(controls.gain_base);
  gain.parameter('depth').expose(controls.gain_depth);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(oscillator.output('out'), gain.input('audio'));
  graph.connect(lfo.output('out'), compare.input('cv'));
  graph.connect(compare.output('gate'), gain.input('cv'));
  graph.connect(gain.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.oscillator_waveform,
    controls.oscillator_frequency,
    controls.oscillator_level,
    controls.lfo_waveform,
    controls.lfo_rate,
    controls.compare_direction,
    controls.compare_threshold,
    controls.compare_hysteresis,
    controls.gain_base,
    controls.gain_depth
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
